def sequence(n):
    def generate(s):
        result = []
        i = 0
        length = len(s)
        while i < length:
            count = 1
            while i + 1 < length and s[i] == s[i+1]:
                i += 1
                count += 1
            result.append((count, s[i]))
            i += 1
        return result

    def next_term(curr):
        description = []
        for count, val in curr:
            if val == '0':
                description.append('0')
            else:
                description.append(str(count))
                description.append('1')
        return ''.join(description)

    if n == 1:
        return '0'
    elif n == 2:
        return '1'

    terms = ['0', '1']
    for _ in range(2, n):
        terms.append(next_term(generate(terms[-1])))

