def get_Inv_Count(arr):
    # Helper function to perform merge sort and count inversions
    def merge_sort_and_count(arr, left, right):
        if left >= right:
            return 0

        mid = (left + right) // 2
        count = merge_sort_and_count(arr, left, mid)
        count += merge_sort_and_count(arr, mid + 1, right)
        count += merge(arr, left, mid, right)
        return count

    # Helper function to merge two sorted arrays and count inversions
    def merge(arr, left, mid, right):
        temp = []
        i = left
        j = mid + 1
        count = 0

        while i <= mid and j <= right:
            if arr[i] <= arr[j]:
                temp.append(arr[i])
                i += 1
            else:
                temp.append(arr[j])
                j += 1
                count += (mid - i + 1)

        while i <= mid:
            temp.append(arr[i])
            i += 1
        while j <= right:
            temp.append(arr[j])
            j += 1

        for idx in range(len(temp)):
            arr[left + idx] = temp[idx]

        return count

    return merge_sort_and_count(arr, 0, len(arr) - 1)
